#define BG_BIAS               -2.38307264f

/* Adaptive threshold (CFAR). Track the background at the 0.2 quantile over a
 * trailing 300 s and subtract it, so one theta means the same thing in every
 * recording. Divide by a LOCAL spread and discrimination collapses — see adapt.py;
 * BG_GLOBAL_SCALE is fitted on TRAIN and travels with the model. */
#define BG_WIN_S              1.0f
#define BG_ADAPT_WINDOW_S     300.0f
#define BG_ADAPT_N            300     /* scores in the trailing ring: window_s / win_s */
#define BG_ADAPT_QUANTILE     0.2f
#define BG_GLOBAL_SCALE       1.59267049f
#define BG_MIN_SCALE          0.001f   /* floor on the divisor */
#define BG_AGG_N              3      /* z = max over the last N z-scores */

/* Gate state machine. Mirrors birdgate/gate.py — must be bit-identical in behaviour. */
#define BG_THETA_ON           0.316723114f
#define BG_THETA_OFF          0.0667231145f   /* theta_on - hysteresis_margin */
#define BG_PRE_ROLL_S         1.0f
#define BG_HANGOVER_S         1.0f
#define BG_MIN_ON_S           20.0f
#define BG_RECHECK_S          1.0f   /* the gate can only close at a recheck */

